contract InvMutTest {
    C c;
    address deployer;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function taking inputs: target address and desired freeze flag
    function run(address target, bool freeze) public payable {
        require(address(this) != address(0)); // trivial sanity so params used

        // Observe owner and frozen status before any calls
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        bool frozenBefore = c.frozenAccount(target); if (__ESBMC_reverted()) return;

        // Attempt call as non-owner: since this contract is the deployer of c, msg.sender for c calls will be this contract.
        // To simulate a non-owner caller we need to call freezeAccount from this contract when this contract is not the owner.
        // If this contract is the owner, first transfer ownership-like control cannot be done (no setter), so we detect both cases.

        bool nonOwnerReverted;
        // If this contract is owner, then calling freezeAccount should succeed; otherwise it should revert.
        // Try call and record whether it reverted.
        c.freezeAccount(target, freeze); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            nonOwnerReverted = true;
        } else {
            nonOwnerReverted = false;
        }

        // Read frozen status after attempted call
        bool frozenAfter = c.frozenAccount(target); if (__ESBMC_reverted()) return;
        address ownerAfter = c.owner(); if (__ESBMC_reverted()) return;

        // Assert general rule: if this contract is not the owner, call must revert and frozen flag unchanged;
        // if this contract is the owner, call must not revert and frozen flag equals the requested value.
        assert(
            (ownerBefore != address(this) && nonOwnerReverted && frozenAfter == frozenBefore && ownerAfter == ownerBefore)
            ||
            (ownerBefore == address(this) && !nonOwnerReverted && frozenAfter == freeze && ownerAfter == ownerBefore)
        );
    }

    receive() external payable {}
}

