// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;
    address deployer;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address target, bool freeze) internal {
        vm.assume(address(this) != address(0));
        address ownerBefore;
        try c.owner() returns (address __r) { ownerBefore = __r; } catch { return; }
        bool frozenBefore;
        try c.frozenAccount(target) returns (bool __r) { frozenBefore = __r; } catch { return; }
        bool nonOwnerReverted;
        try c.freezeAccount(target, freeze) {
            nonOwnerReverted = false;
        } catch {
            nonOwnerReverted = true;
        }
        bool frozenAfter;
        try c.frozenAccount(target) returns (bool __r) { frozenAfter = __r; } catch { return; }
        address ownerAfter;
        try c.owner() returns (address __r) { ownerAfter = __r; } catch { return; }
        assertTrue((ownerBefore != address(this) && nonOwnerReverted && frozenAfter == frozenBefore && ownerAfter == ownerBefore)
            ||
            (ownerBefore == address(this) && !nonOwnerReverted && frozenAfter == freeze && ownerAfter == ownerBefore));
    }

    function testFuzz_run(address target, bool freeze) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(target, freeze);
    }

    receive() external payable {}
}
